/*board.boardList*/ Select /*+ index_asc(icomboard icomboard_pk) */ BID, COMPANY, SUBJECT, REG_USER_NAME, (SELECT EMAIL FROM ICOMLUSR WHERE COM_CODE = COMPANY AND USER_ID = REG_USER_ID) EMAIL, REG_DATE, ACL, LCOUNT, DECODE(BTYPE,'NT','공지사항', 'EB','e-Biz뉴스', 'DI','전시회소식', 'EM','e마켓자료실', 'SI','상품자료실', 'BD','게시판', 'PI','구매정보') BTYPE_DIS, DECODE(ACL,'INC','자사', 'BUY','구매사', 'SEL','판매사', 'KEP','KEP', 'MEB','회원전체', 'CST','특정회사', 'UST','특정사용자', 'ALL','전체') ACL_DIS, BTYPE, TO_DATE, FROM_DATE, (SELECT COM_NAME_LOC FROM ICOMCMPY WHERE COM_CODE = COMPANY) COM_NAME_LOC, BLEVEL, VID, OPEN_FLAG From ICOMBOARD Where STATUS ! ='D'
AND FROM_DATE <= #{startDate} AND TO_DATE >= #{startDate}
AND BTYPE = #{sbtype}
AND ACL = #{sacl}
AND OPEN_FLAG = #{st_open_flag}
Order By BID desc

mapper.update:
SELECT MAX(NVL(BID,1))+1 AS BID FROM ICOMBOARD WHERE BTYPE = #{BTYPE}
/*board.boardWrite*/ Insert into ICOMBOARD( BID ,BTYPE ,COMPANY ,STATUS ,VID ,PID ,BLEVEL ,ACL ,LCOUNT ,SORT ,SUBJECT ,CONTEXT ,REG_USER_ID ,REG_DATE ,REG_TIME ,REG_DEP ,REG_DEP_NAME ,IMAGE_KEY ,PASSWORD ,REG_USER_NAME ,OPEN_FLAG ,FROM_DATE ,TO_DATE ) values ( #{BID} ,#{BTYPE} ,#{COMPANY} ,'C' ,#{BID} * 10 ,#{BID} ,0 ,#{ACL} ,0 ,'' ,#{SUBJECT} ,#{CONTEXT} ,#{REG_USER_ID} ,to_char(sysdate,'YYYYMMDD') ,to_char(sysdate,'HH24MISS') ,#{REG_DEP} ,#{REG_DEP_NAME} ,#{IMAGE_KEY} ,'' ,#{REG_USER_NAME}
, 'Y'
, 'N'
,replace(#{FROM_DATE},'/','') ,replace(#{TO_DATE},'/','') )

		 /*board.deleteICOMBDDT*/

 		 	DELETE FROM  ICOMBDDT 
				WHERE BID = #{BID}		
				AND BTYPE = #{BTYPE}

		 /*board.updateBoardLCount*/

 		 	UPDATE ICOMBOARD SET
			    LCOUNT = LCOUNT+1
			WHERE BTYPE = #{BTYPE}
				AND BID = #{BID}

		/*board.boardUpdate*/

 		 	UPDATE  ICOMBOARD SET  
 		 		 ACL = #{ACL}	  
				,SUBJECT = #{SUBJECT}		
				,CONTEXT = #{CONTEXT}		  
				,IMAGE_KEY = #{IMAGE_KEY}		  
				,FROM_DATE = REPLACE(#{FROM_DATE},'/','')
				,TO_DATE = REPLACE(#{TO_DATE},'/','')
				WHERE BID = #{BID}		
				AND BTYPE = #{BTYPE}

		/*board.boardDelete*/

 		 	DELETE FROM  ICOMBOARD 
				WHERE BID = #{BID}		
				AND BTYPE = #{BTYPE}


		/*board.boardConfirm*/
		UPDATE ICOMBOARD SET




				OPEN_FLAG =  'Y'




				OPEN_FLAG =  'N'




		WHERE BID = #{BID}  
           AND BTYPE = #{BTYPE}
